// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by sub.distribution@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before sub.distribution started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "sub.distribution",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "sub.distribution", capability_version: "1.0.0",
  layer: "subsystem", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// GENERATED gate. Re-verifies what an upstream subsystem already checked.
// Cheap, and it makes a mis-wired caller fail CLOSED rather than publish.
const CHECKS = ["approval","compliance","brand","rights"];
const env = $('Envelope In').first().json;
const gates = { ...(env.payload?.gates ?? {}), ...($json.gates ?? {}) };
const PASS = { compliance: ['pass', 'warn'], brand: ['pass', 'warn'], rights: ['pass'], approval: ['approved', 'not_required'] };
const failed = [];
for (const c of CHECKS) {
  const v = gates[c] ?? (c === 'approval' ? gates.human_approval : undefined);
  if (v === undefined) { failed.push({ check: c, reason: 'not_evaluated' }); continue; }
  if (!(PASS[c] ?? ['pass']).includes(v)) failed.push({ check: c, reason: 'status_' + v });
}
return [{ json: { ...$json, gate_pass: failed.length === 0, gate_failures: failed } }];

// One PublishRequest per channel slot, with a deterministic idempotency key so a replayed
// run cannot double-post. The key is the whole reason a retry is safe here.
const crypto = require('crypto');
const e = $('Envelope In').first().json;
const p = e.payload;
const reqs = (p.slots || []).map((slot, i) => {
  const content = (p.copy || []).find(c => c.slot?.channel === slot.channel && c.slot?.format === slot.format) || (p.copy || [])[i] || {};
  const assets = (p.assets || []).filter(a => !a.channel_fit || a.channel_fit.includes(slot.channel));
  const body = [content.hook, content.body].filter(Boolean).join('\n\n');
  const key = crypto.createHash('sha256').update([e.tenant_id, slot.channel, slot.format, body, assets.map(a => a.asset_id).join(',')].join('|')).digest('hex');
  return {
    request_id: 'pub_' + key.slice(0, 16),
    tenant_id: e.tenant_id,
    brand_id: e.brand_id,
    trace_id: e.trace_id,
    channel: slot.channel,
    format: slot.format,
    account_ref: p.accounts?.[slot.channel] || null,
    content: { title: content.title || null, body, caption: content.caption || content.body || null, hashtags: content.hashtags || [], link: content.link || null, alt_text: content.alt_text || null, first_comment: content.first_comment || null, asset_ids: assets.map(a => a.asset_id), asset_urls: assets.map(a => a.public_url) },
    schedule: p.schedule || { mode: 'now' },
    gates: p.gates || {},
    idempotency_key: key,
    dry_run: p.dry_run === true
  };
});
return reqs.map(r => ({ json: r }));

// GENERATED by compiler/router.mjs — do not edit in the n8n canvas.
// Resolves the abstract capability tag "distribute.publish" to a concrete implementation.
// Precedence: hard_rule -> vertical_binding -> policy_table -> model -> default
const TAG = "distribute.publish";
const POLICY = {
  "precedence": [
    "hard_rule",
    "vertical_binding",
    "policy_table",
    "model",
    "default"
  ],
  "hard_rules": [
    {
      "id": "HR-001-regulated-claim-requires-human",
      "description": "Any claim tagged `regulated` (health outcome, financial return, legal result, efficacy) goes to a human before it can reach the public, regardless of tenant autonomy setting.",
      "when": {
        "brief.message.key_claims[].risk": {
          "any_of": [
            "regulated"
          ]
        }
      },
      "then": {
        "action": "require_approval",
        "reason_code": "REGULATED_CLAIM",
        "message": "Regulated claim detected; human sign-off required before distribution."
      },
      "severity": "block"
    },
    {
      "id": "HR-002-paid-media-always-approved",
      "description": "Paid channels spend money per impression. Never autonomous.",
      "when": {
        "context.channel_kind": {
          "eq": "paid"
        }
      },
      "then": {
        "action": "require_approval",
